# Check whether the published edge-expansion conditions preserve both disjointness constraints.
edges={(s,t) for s in ('s1','s2') for t in ('t1','t2')}
train_seed={('s1','t1')}; test_seed={('s2','t2')}
train_subjects={s for s,t in train_seed}; test_subjects={s for s,t in test_seed}
train_stimuli={t for s,t in train_seed}; test_stimuli={t for s,t in test_seed}
eeg_train=train_seed|{(s,t) for s,t in edges if s not in test_subjects}
eeg_test=test_seed|{(s,t) for s,t in edges if s not in train_subjects}
fmri_train=train_seed|{(s,t) for s,t in edges if t not in test_stimuli}
fmri_test=test_seed|{(s,t) for s,t in edges if t not in train_stimuli}
print('Algorithm 1, line 15: stimulus overlap after expansion:',sorted({t for s,t in eeg_train}&{t for s,t in eeg_test}))
